# -*- coding: utf-8 -*-
import os, re, json

REPOS = r"D:\repository"

# each check: repo, list of (relative glob-ish subpath, [regex patterns])
CHECKS = {
 "1 eid_verify_replace": ("昆山市民", ["src"], [
    r"initEid", r"getEidToken", r"faceRecognition", r"mp_ecard_sdk", r"wx0e2cb0b052a91c92", r"useEidVerify"]),
 "2 adv_filter_eq": ("苏住房G", [r"zhi2-web-admin\src"], [
    r"sanitizeConditionGroups", r"condition\.operator", r"advancedQueryCore"]),
 "3 todo_id_fix": ("苏州市房地产监测V3", ["src"], [
    r"resolveIdFromRoute", r"routeCompanyRecordId", r"getEntryNetworkDetail", r"buildTableIdNavigation"]),
 "4 unit_elevator_dict": ("苏州市房地产监测V3", ["src"], [
    r"have_or_not", r"sys_include", r"unitinfo", r"unitChange"]),
 "5 cascader_lazy": ("园区公共收益", ["src"], [
    r"projectNameExampleDialog", r"facilityDefinition/listTree", r"originalOptions", r"ProjectNameDialog"]),
 "6 zpaging_fixed_popup": ("苏住房C", ["src"], [
    r"z-paging", r"min-height:\s*500rpx", r"max-height:\s*75vh", r"use-page-scroll"]),
 "7 suzhou_e2e": ("苏住房G", ["e2e"], [
    r"createSuite", r"1234", r"8101", r"ctx\.ui\.login"]),
 "8 decision_range_dynamic": ("太仓G", ["src"], [
    r"DecisionRangeTable", r"doLayout", r"showSuccess", r"decisionId"]),
 "9 tip_icon_static": ("苏住房C", ["src"], [
    r"MAIN_STATIC_PATHS", r"tip-szf\.png", r"resolveStaticUrl"]),
 "10 cert_detail_grid": ("苏州市房地产监测V3", ["src"], [
    r"sys_user_sex", r"personnelCertificate", r"qualifications"]),
}

def scan(repo, subdirs, pats):
    root = os.path.join(REPOS, repo)
    regexes = [(p, re.compile(p)) for p in pats]
    hits = {p: [] for p in pats}
    found_files = 0
    for sub in subdirs:
        base = os.path.join(root, sub)
        for dp, dns, fns in os.walk(base):
            dns[:] = [d for d in dns if d not in ("node_modules", ".git", "dist", "unpackage")]
            for fn in fns:
                if not fn.endswith((".vue", ".js", ".ts", ".mjs", ".cjs", ".json")):
                    continue
                fp = os.path.join(dp, fn)
                try:
                    with open(fp, "r", encoding="utf-8", errors="ignore") as f:
                        txt = f.read()
                except Exception:
                    continue
                found_files += 1
                for p, rx in regexes:
                    if rx.search(txt):
                        rel = os.path.relpath(fp, root).replace("\\", "/")
                        if len(hits[p]) < 2:
                            hits[p].append(rel)
    out = {}
    for p in pats:
        out[p] = hits[p]
    return found_files, out

res = {}
for key, (repo, subdirs, pats) in CHECKS.items():
    root = os.path.join(REPOS, repo)
    exists = os.path.isdir(root)
    if not exists:
        res[key] = {"repo": repo, "repo_exists": False}
        continue
    nf, hits = scan(repo, subdirs, pats)
    res[key] = {"repo": repo, "repo_exists": True, "scanned_files": nf, "hits": hits}

print(json.dumps(res, ensure_ascii=False, indent=1))

